0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":3115,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 10.42\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T6bd,"])self.__next_f.push([1,"There is a Mission that regularly propounds that worship of any demigod will lead one to the Supreme Personality of Godhead, or the supreme goal. But worship of demigods is thoroughly discouraged herein because even the greatest demigods like Brahmā and Śiva represent only part of the opulence of the Supreme Lord. He is the origin of everyone born, and no one is greater than Him. He is asamaurdhva, which means that no one is superior to Him and that no one is equal to Him. In the Padma Purāṇa it is said that one who considers the Supreme Lord Kṛṣṇa in the same category with demigods – be they even Brahmā or Śiva – becomes at once an atheist. If, however, one thoroughly studies the different descriptions of the opulences and expansions of Kṛṣṇa’s energy, then one can understand without any doubt the position of Lord Śrī Kṛṣṇa and can fix his mind in the worship of Kṛṣṇa without deviation. The Lord is all-pervading by the expansion of His partial representation, the Supersoul, who enters into everything that is. Pure devotees, therefore, concentrate their minds in Kṛṣṇa consciousness in full devotional service; therefore they are always situated in the transcendental position. Devotional service and worship of Kṛṣṇa are very clearly indicated in this chapter in verses 8 through 11. That is the way of pure devotional service. How one can attain the highest devotional perfection of association with the Supreme Personality of Godhead has been thoroughly explained in this chapter. Śrīla Baladeva Vidyābhūṣaṇa, a great ācārya in disciplic succession from Kṛṣṇa, concludes his commentary on this chapter by saying,"])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":3115,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"42\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 42\",\"advanced_view_url_path\":\"/en/library/bg/10/advanced-view/#bb2753\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/10/42/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/10/42/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/10/42/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/10/42/\"},{\"display_name\":\"Eng